    const svg = el.querySelector('svg'), rig = new KongRig(svg);
    // 높이 뛰면(2단 점프) 그림이 자기 상자 밖으로 나가 잘린다 → 그림 좌표는 그대로 두고 상자만 위·옆으로 넓힌다 (CSS 와 짝)
