    const st = rig.poses.stand, FIX = { jump: [62, -6], land: [44, 46] };
    if (st) for (const fr of st.frames) if (FIX[fr.name] && !fr.head) fr.head = [st.head[0] + FIX[fr.name][0], st.head[1] + FIX[fr.name][1], st.head[2] || 1];
