    k.setPose = p => { rig.setPose(k.has(p) ? p : 'sit'); return k; };
    k.setSize = px => { k.size = px; el.style.width = el.style.height = px + 'px'; return k; };
    k.render = o => { k.opts = o || {}; rig.render(Object.assign({ outfit: share.outfit || 'none', ribbon: !!share.ribbon, tailAmp: 8, tailRate: 2 }, o, rig.pose === 'stand' ? null : { facing: 1 })); return k; };
    k.place = (x, y, scale) => { k.x = x; k.y = y; k.scale = scale || 1; el.style.transform = 'translate(' + (x - k.size / 2).toFixed(1) + 'px,' + (y - k.size * 0.95).toFixed(1) + 'px) scale(' + k.scale.toFixed(3) + ')'; return k; };
