      const scrim = document.createElement('div'); scrim.className = 'kg-scrim kg-rules';
      const card = document.createElement('div'); card.className = 'kg-card'; card.setAttribute('role', 'dialog'); card.setAttribute('aria-modal', 'true'); card.setAttribute('aria-label', (o.title || '게임') + ' 규칙');
      const tag = document.createElement('div'); tag.className = 'tag'; tag.textContent = '게임 규칙'; card.appendChild(tag);
      const h = document.createElement('h2'); h.textContent = o.title || ''; card.appendChild(h);
      if (o.lead) { const p = document.createElement('p'); p.textContent = o.lead; card.appendChild(p); }
      const ul = document.createElement('ul');
      for (const it of o.items || []) { const li = document.createElement('li'), i = document.createElement('i'), s = document.createElement('span'); i.textContent = it[0]; i.setAttribute('aria-hidden', 'true'); s.textContent = it[1]; li.appendChild(i); li.appendChild(s); ul.appendChild(li); }
      card.appendChild(ul);
